import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, loadTestFile, unzipInputArray } from '../test-utils'
import { XMLParser } from 'fast-xml-parser'

describe('data-processing-subflow: Round-Trip Test', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, '../project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('data-processing-subflow: Round-trip transformation', async () => {
        const xmlFileName = 'sys_hub_flow_72bd5ee93f434a028263ef70bd626b48.xml'
        const project = ctx.createProject()

        // ============================================================================
        // Step 1: XML → Fluent Transformation
        // ============================================================================
        const xmlContent = loadTestFile(xmlFileName, 'example-unit-tests/xml')
        const { changedFiles } = await project.transform({
            path: xmlFileName,
            content: xmlContent,
        })

        expect(changedFiles).toHaveLength(1)
        const fluentContent = changedFiles[0].getContent()
        const fluentFileName = changedFiles[0].getName()

        // Verify imports
        expect(fluentContent).toContain('import {')
        expect(fluentContent).toContain('Subflow')
        expect(fluentContent).toContain('FlowObject')
        expect(fluentContent).toContain('FlowArray')
        expect(fluentContent).toContain('action')
        expect(fluentContent).toContain('wfa')

        // Subflow definition
        expect(fluentContent).toContain('Subflow(')
        expect(fluentContent).toContain("name: 'Data Processing Subflow'")

        // Inputs - priority
        expect(fluentContent).toContain('priority: IntegerColumn')
        expect(fluentContent).toContain("label: 'Priority Level'")

        // Inputs - description
        expect(fluentContent).toContain('description: StringColumn')
        expect(fluentContent).toContain("label: 'Description'")

        // Inputs - dueDate
        expect(fluentContent).toContain('dueDate: DateTimeColumn')
        expect(fluentContent).toContain("label: 'Due Date'")

        // Inputs - category
        expect(fluentContent).toContain('category: StringColumn')
        expect(fluentContent).toContain("label: 'Processing Category'")

        // Inputs - configuration (FlowObject nested)
        expect(fluentContent).toContain('configuration: FlowObject')
        expect(fluentContent).toContain('environment: StringColumn')
        expect(fluentContent).toContain('batchSize: IntegerColumn')
        expect(fluentContent).toContain('settings: FlowObject')
        expect(fluentContent).toContain('retryCount: IntegerColumn')

        // Inputs - items (FlowArray)
        expect(fluentContent).toContain('items: FlowArray')
        expect(fluentContent).toContain("childName: 'ProcessingItem'")

        // Inputs - assignedTo (Reference)
        expect(fluentContent).toContain('assignedTo: ReferenceColumn')
        expect(fluentContent).toContain("referenceTable: 'sys_user'")

        // Outputs
        expect(fluentContent).toContain('success: BooleanColumn')
        expect(fluentContent).toContain('processedCount: IntegerColumn')
        expect(fluentContent).toContain('resultMessage: StringColumn')

        // Action 1: Initial log
        expect(fluentContent).toContain('wfa.action(')
        expect(fluentContent).toContain('action.core.log')
        expect(fluentContent).toContain("annotation: 'Log the start of data processing'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Starting data processing')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.priority, 'integer')")
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.category, 'string')")

        // forEach loop
        expect(fluentContent).toContain('wfa.flowLogic.forEach(')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.items, 'array.object')")
        expect(fluentContent).toContain("annotation: 'Process each item in the array'")

        // Nested if inside forEach
        expect(fluentContent).toContain('wfa.flowLogic.if(')
        expect(fluentContent).toContain("annotation: 'Check if item is active'")
        expect(fluentContent).toMatch(/condition:\s*`\$\{wfa\.dataPill\(item[^.]*\.active,\s*'boolean'\)\}=true`/)

        // Action 2: Log item (inside forEach)
        expect(fluentContent).toContain("annotation: 'Log processing of individual item'")
        expect(fluentContent).toContain("log_level: 'info'")
        expect(fluentContent).toContain('log_message: `Processing item:')
        expect(fluentContent).toMatch(/wfa\.dataPill\(item[^.]*\.name,\s*'string'\)/)
        expect(fluentContent).toContain('with ID:')
        expect(fluentContent).toMatch(/wfa\.dataPill\(item[^.]*\.id,\s*'string'\)/)

        // If logic: Check urgent priority
        expect(fluentContent).toContain("annotation: 'Check if priority is urgent (1)'")
        expect(fluentContent).toMatch(/condition:\s*`\$\{wfa\.dataPill\(_params\.inputs\.priority,\s*'integer'\)\}=1`/)

        // Action 3: Log urgent
        expect(fluentContent).toContain("annotation: 'Log urgent priority processing'")
        expect(fluentContent).toContain("log_level: 'warn'")
        expect(fluentContent).toContain('log_message: `Urgent data processing started')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.description, 'string')")
        expect(fluentContent).toContain('Due date:')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.dueDate, 'string')")

        // ElseIf logic: Check high priority
        expect(fluentContent).toContain('wfa.flowLogic.elseIf(')
        expect(fluentContent).toContain("annotation: 'Check if priority is high (2)'")
        expect(fluentContent).toMatch(/condition:\s*`\$\{wfa\.dataPill\(_params\.inputs\.priority,\s*'integer'\)\}=2`/)

        // Action 4: Log high priority
        expect(fluentContent).toContain("annotation: 'Log high priority processing'")
        expect(fluentContent).toContain("log_level: 'warn'")
        expect(fluentContent).toContain('log_message: `High priority data processing in progress')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.description, 'string')")

        // assignSubflowOutputs
        expect(fluentContent).toContain('wfa.flowLogic.assignSubflowOutputs(')
        expect(fluentContent).toContain("annotation: 'Assign processing results to subflow outputs'")
        expect(fluentContent).toContain('_params.outputs')
        expect(fluentContent).toContain('success: true')
        expect(fluentContent).toContain('processedCount: 5')
        expect(fluentContent).toContain('resultMessage: `Successfully processed data for category')
        expect(fluentContent).toContain("wfa.dataPill(_params.inputs.category, 'string')")

        // ============================================================================
        // Step 2: Fluent → XML Transformation
        // ============================================================================
        const tempProject = ctx.createProject()
        tempProject.addFile({ path: fluentFileName, content: fluentContent })

        const output = await tempProject.getFile(fluentFileName)?.getOutput()
        expect(output.length).toBeGreaterThan(0)

        // ============================================================================
        // Step 3: Parse and Validate Regenerated XML
        // ============================================================================
        const parser = new XMLParser({ ignoreAttributes: false })
        const mergedRecords: Record<string, any[]> = {}

        for (const file of output) {
            const parsed = parser.parse(file.content)['record_update']
            Object.entries(parsed).forEach(([table, value]) => {
                if (!mergedRecords[table]) {
                    mergedRecords[table] = []
                }
                if (Array.isArray(value)) {
                    mergedRecords[table].push(...value)
                } else if (value && typeof value === 'object') {
                    mergedRecords[table].push(value)
                }
            })
        }

        expect(mergedRecords['sys_hub_flow']).toBeDefined()
        expect(mergedRecords['sys_hub_action_instance_v2']).toBeDefined()
        expect(mergedRecords['sys_hub_flow_logic_instance_v2']).toBeDefined()

        // Validate subflow record
        const flows = mergedRecords['sys_hub_flow']
        const subflow = flows.find((f: any) => f.name === 'Data Processing Subflow')
        expect(subflow).toBeDefined()
        expect(subflow.type).toBe('subflow')
        expect(subflow.generation_source).toBe('fluent')

        // Validate actions
        const actionInstances = mergedRecords['sys_hub_action_instance_v2']
        expect(actionInstances.length).toBeGreaterThanOrEqual(4)

        // Action 1: Initial log
        const logStart = actionInstances.find((a: any) => a.comment?.includes('Log the start of data processing'))
        expect(logStart).toBeDefined()
        const logStartValues = unzipInputArray(logStart.values)
        const logStartVar = (name: string) => findInput(logStartValues, name)?.value
        expect(logStartVar('log_level')).toBe('info')
        expect(logStartVar('log_message')).toContain('Starting data processing')
        expect(logStartVar('log_message')).toContain('priority')
        expect(logStartVar('log_message')).toContain('category')

        // Action 2: Log item processing (inside forEach)
        const logItem = actionInstances.find((a: any) => a.comment?.includes('Log processing of individual item'))
        expect(logItem).toBeDefined()
        const logItemValues = unzipInputArray(logItem.values)
        const logItemVar = (name: string) => findInput(logItemValues, name)?.value
        expect(logItemVar('log_level')).toBe('info')
        expect(logItemVar('log_message')).toContain('Processing item')
        expect(logItemVar('log_message')).toContain('with ID')

        // Action 3: Log urgent priority
        const logUrgent = actionInstances.find((a: any) => a.comment?.includes('Log urgent priority processing'))
        expect(logUrgent).toBeDefined()
        const logUrgentValues = unzipInputArray(logUrgent.values)
        const logUrgentVar = (name: string) => findInput(logUrgentValues, name)?.value
        expect(logUrgentVar('log_level')).toBe('warn')
        expect(logUrgentVar('log_message')).toContain('Urgent data processing')
        expect(logUrgentVar('log_message')).toContain('Due date')

        // Action 4: Log high priority
        const logHigh = actionInstances.find((a: any) => a.comment?.includes('Log high priority processing'))
        expect(logHigh).toBeDefined()
        const logHighValues = unzipInputArray(logHigh.values)
        const logHighVar = (name: string) => findInput(logHighValues, name)?.value
        expect(logHighVar('log_level')).toBe('warn')
        expect(logHighVar('log_message')).toContain('High priority data processing')

        // Validate flow logic
        const flowLogicInstances = mergedRecords['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances.length).toBeGreaterThanOrEqual(5)

        // forEach loop
        const forEach = flowLogicInstances.find((fl: any) => fl.comment?.includes('Process each item in the array'))
        expect(forEach).toBeDefined()
        const forEachValues = unzipInputArray(forEach.values)
        // forEach values are in a different structure - validate the decompressed data contains items
        const forEachData = JSON.stringify(forEachValues)
        expect(forEachData).toContain('subflow.items')

        // If logic: Check active
        const ifActive = flowLogicInstances.find((fl: any) => fl.comment?.includes('Check if item is active'))
        expect(ifActive).toBeDefined()
        const ifActiveValues = unzipInputArray(ifActive.values)
        const ifActiveData = JSON.stringify(ifActiveValues)
        expect(ifActiveData).toContain('active')
        expect(ifActiveData).toContain('=true')

        // If logic: Check urgent priority
        const ifUrgent = flowLogicInstances.find((fl: any) => fl.comment?.includes('Check if priority is urgent'))
        expect(ifUrgent).toBeDefined()
        const ifUrgentValues = unzipInputArray(ifUrgent.values)
        const ifUrgentData = JSON.stringify(ifUrgentValues)
        expect(ifUrgentData).toContain('subflow.priority')
        expect(ifUrgentData).toContain('=1')

        // ElseIf logic: Check high priority
        const elseIfHigh = flowLogicInstances.find((fl: any) => fl.comment?.includes('Check if priority is high'))
        expect(elseIfHigh).toBeDefined()
        const elseIfHighValues = unzipInputArray(elseIfHigh.values)
        const elseIfHighData = JSON.stringify(elseIfHighValues)
        expect(elseIfHighData).toContain('subflow.priority')
        expect(elseIfHighData).toContain('=2')

        // assignSubflowOutputs
        const assignOutputs = flowLogicInstances.find((fl: any) => fl.comment?.includes('Assign processing results'))
        expect(assignOutputs).toBeDefined()
        const assignOutputsValues = unzipInputArray(assignOutputs.values) as any
        const assignOutputsVar = (name: string) =>
            assignOutputsValues.outputsToAssign.find((v: any) => v.name === name)?.value
        expect(assignOutputsVar('success')).toBe('true')
        expect(assignOutputsVar('processedCount')).toBe('5')
        expect(assignOutputsVar('resultMessage')).toContain('Successfully processed data')
        expect(assignOutputsVar('resultMessage')).toContain('{{subflow.category}}')
    })
})
